package com.guocheng.mediapocket;
import java.util.*;
public class FusionPlaybackRulesTest {
 static void check(boolean b,String message){if(!b)throw new AssertionError(message);}
 public static void main(String[] args)throws Exception{List<FusionPlaybackRules.Route> routes=FusionPlaybackRules.alternatives("原线$$$备线$$$另线","S01E01.mkv$one#S01E02.mkv$two$$$S1E1.mp4$three#S01E02$four$$$S01E01$three#S01E01$five","S01E01.mkv","one");check(routes.size()==2,"only same episode with unique values");check(routes.get(0).value.equals("three")&&routes.get(1).value.equals("five"),"alternate route values retained");check(FusionPlaybackRules.alternatives("a$$$b","第01集$one$$$第02集$two","第01集","one").isEmpty(),"never select a different episode");check(FusionPlaybackRules.alternatives("a","S01E01$1#S01E01$2#S01E01$3#S01E01$4#S01E01$5","S01E01","1").size()==3,"bounded attempts");check(FusionPlaybackRules.sameFilm("Silo","2023","Silo (2023)","2023"),"same movie and year");check(!FusionPlaybackRules.sameFilm("Silo","2024","Silo","2023"),"do not auto choose another release year");check(!FusionPlaybackRules.sameFilm("Silo II","2023","Silo","2023"),"do not auto choose similar title");check(FusionPlaybackRules.sameEpisode("S02E04.mkv","第04集","第2季"),"explicit season+episode mapping");check(!FusionPlaybackRules.sameEpisode("S02E04","第04集","第1季"),"do not switch seasons");check(!FusionPlaybackRules.sameEpisode("S02E04","04","默认"),"do not infer unknown season");check(FusionPlaybackRules.sameEpisode("S01E01.mkv","第一集","第一季"),"Chinese season and episode");check(FusionPlaybackRules.sameEpisode("S01E01","01","第一季"),"zero-padded numeric episode");check(FusionPlaybackRules.sameEpisode("S02E12","第十二集","第二季"),"Chinese tens");check(FusionPlaybackRules.episode("第1集", "默认").number==1,"unlabelled season retains episode number");check(!FusionPlaybackRules.sameEpisode("S01E01","第1集","默认"),"unknown season offered manually rather than auto-selected");check(FusionPlaybackRules.differentEpisode("S01E01","第2集",""),"do not resume different episode as same one");check(FusionPlaybackRules.routeList("默认","第1集$one#第2集$two","S01E01.mkv",true,true,"影片").isEmpty(),"unlabelled season is not auto-selected");check(FusionPlaybackRules.routeList("默认","第1集$one#第2集$two","S01E01.mkv",true,false,"影片").size()==2,"screenshot regression: manual picker keeps returned episodes when confirmed match is empty");check(FusionPlaybackRules.routeList("第一季","第1集$one#第2集$two","S01E01.mkv",true,true,"影片").size()==1,"labelled season auto-matches only current episode");org.json.JSONArray choices=FusionPlaybackRules.episodeChoices("线路","第1集$a#第2集$b$$$第161集$c","watch-161","第161集");check(choices.length()==3&&choices.getJSONObject(2).getInt("episode")==161&&choices.getJSONObject(2).getString("id").equals("watch-161")&&choices.getJSONObject(0).getString("fusion.value").equals("a"),"episode list keeps every episode and the playing id");StringBuilder many=new StringBuilder();for(int i=1;i<=1200;i++){if(i>1)many.append('#');many.append("第").append(i).append("集$u").append(i);}org.json.JSONArray longList=FusionPlaybackRules.episodeChoices("线",many.toString(),"watch","第161集");check(longList.length()==1200&&longList.getJSONObject(160).getInt("episode")==161&&longList.getJSONObject(160).getString("id").equals("watch"),"episode list is not cut at the mixed-route cap");System.out.println("PASS: identical episode only, original selection excluded, duplicate URLs excluded, bounded fallback count.");}
}
